import{_ as r,c as t,o as i,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"Interaction RPC 服务","description":"","frontmatter":{"title":"Interaction RPC 服务","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#4","branch":"main","level":0,"order":4},"headers":[],"relativePath":"posts/projects/zfeed/04-interaction-rpc-service/index.md","filePath":"posts/projects/zfeed/04-interaction-rpc-service/index.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/04-interaction-rpc-service/index.md"};function n(c,e,l,p,b,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="interaction-rpc-服务" tabindex="-1">Interaction RPC 服务 <a class="header-anchor" href="#interaction-rpc-服务" aria-label="Permalink to &quot;Interaction RPC 服务&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction.go" target="_blank" rel="noreferrer">app/rpc/interaction/interaction.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction/interaction.pb.go" target="_blank" rel="noreferrer">app/rpc/interaction/interaction/interaction.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/real_store_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/real_store_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/removefavoritelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/removefavoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto</a></li></ul></details><p><code>interaction-rpc</code> 服务是 zfeed 生态中的社交引擎。它管理点赞、评论、收藏和关注等用户互动的生命周期。该服务面向高并发和最终一致性设计，通过事件驱动架构把互动变更传播到其他系统，例如用于实时计数更新的 <code>count-rpc</code> 服务。</p><h2 id="服务概览" tabindex="-1">服务概览 <a class="header-anchor" href="#服务概览" aria-label="Permalink to &quot;服务概览&quot;">​</a></h2><p>该服务暴露四个主要 gRPC 接口，每个接口对应一个社交领域：</p><ul><li>LikeService：管理文章、视频和评论的点赞/取消点赞状态。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L285-L291" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#285-291</a></li><li>FavoriteService：处理用户主动整理的内容收藏集合。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L292-L297" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#292-297</a></li><li>CommentService：管理楼中楼讨论和回复。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L298-L305" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#298-305</a></li><li>FollowService：维护用户之间的社交图谱。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L307-L314" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#307-314</a></li></ul><h3 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h3><p>该服务使用 Transactional Outbox Pattern，确保互动事件能可靠投递到 Kafka。当用户执行互动操作（例如点赞内容）时，状态变更会写入主数据库，同时对应事件也会在同一个事务中写入 “outbox” 表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L110-L114" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#110-114</a></p><h4 id="互动数据流" tabindex="-1">互动数据流 <a class="header-anchor" href="#互动数据流" aria-label="Permalink to &quot;互动数据流&quot;">​</a></h4><p>下图展示一次请求如何流经 RPC server，并进入底层存储和事件系统。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction.go#L33-L37" target="_blank" rel="noreferrer">app/rpc/interaction/interaction.go#33-37</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go#L18-L27" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go#18-27</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L110-L114" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#110-114</a></p><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><h3 id="transactional-outbox-与-relay" tabindex="-1">Transactional Outbox 与 Relay <a class="header-anchor" href="#transactional-outbox-与-relay" aria-label="Permalink to &quot;Transactional Outbox 与 Relay&quot;">​</a></h3><p>为了解决 MySQL 和 Kafka 之间的“双写”问题，该服务实现了 relay 机制。</p><ol><li>Producer：<code>LikeProducer</code> 将事件插入 <code>zfeed_like_event_outbox</code> 表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#L51-L53" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#51-53</a></li><li>Relay：后台 <code>LikeOutboxRelay</code> 服务轮询待处理记录，并将其推送到 Kafka。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L211-L224" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#211-224</a></li><li>重试：如果 Kafka 不可用，relay 使用指数退避策略重试投递。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L179-L190" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#179-190</a></li></ol><h3 id="服务上下文" tabindex="-1">服务上下文 <a class="header-anchor" href="#服务上下文" aria-label="Permalink to &quot;服务上下文&quot;">​</a></h3><p><code>ServiceContext</code> 是依赖注入容器，负责管理到 Redis、MySQL（通过 GORM）以及 <code>UserRpc</code>、<code>ContentRpc</code> 等下游 RPC 客户端的连接。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go#L18-L27" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go#18-27</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/svc/servicecontext.go#L18-L27" target="_blank" rel="noreferrer">app/rpc/interaction/internal/svc/servicecontext.go#18-27</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer.go#L48-L54" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer.go#48-54</a></p><h2 id="子系统" tabindex="-1">子系统 <a class="header-anchor" href="#子系统" aria-label="Permalink to &quot;子系统&quot;">​</a></h2><h3 id="点赞与取消点赞系统" tabindex="-1"><a href="./01-like-and-unlike-system.html">点赞与取消点赞系统</a> <a class="header-anchor" href="#点赞与取消点赞系统" aria-label="Permalink to &quot;[点赞与取消点赞系统](./01-like-and-unlike-system.md)&quot;">​</a></h3><p>处理高频点赞/取消点赞操作。它使用 Redis Lua 脚本保证原子性，并通过 <code>LikeOutboxRelay</code> 确保 <code>count-rpc</code> 服务最终收到递增/递减信号。</p><ul><li>关键文件：<code>internal/logic/like</code>、<code>internal/mq/producer/like_producer.go</code>。</li><li>详情请参阅<a href="./01-like-and-unlike-system.html">点赞与取消点赞系统</a>。</li></ul><h3 id="评论系统" tabindex="-1"><a href="./02-comment-system.html">评论系统</a> <a class="header-anchor" href="#评论系统" aria-label="Permalink to &quot;[评论系统](./02-comment-system.md)&quot;">​</a></h3><p>管理支持根评论和回复的层级评论结构。它包含复杂的缓存回填机制，用于处理高流量内容。</p><ul><li>关键文件：<code>internal/logic/comment</code>、<code>internal/repositories/comment_repository.go</code>。</li><li>详情请参阅<a href="./02-comment-system.html">评论系统</a>。</li></ul><h3 id="收藏与关注系统" tabindex="-1"><a href="./03-favorite-and-follow-systems.html">收藏与关注系统</a> <a class="header-anchor" href="#收藏与关注系统" aria-label="Permalink to &quot;[收藏与关注系统](./03-favorite-and-follow-systems.md)&quot;">​</a></h3><p>管理用户收藏集合和社交图谱。Favorite 系统与用户 Feed 集成，提供“用户收藏 Feed”。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go#L152-L155" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go#152-155</a> Follow 系统则维护粉丝/关注数和关系。</p><ul><li>关键文件：<code>internal/logic/favorite</code>、<code>internal/logic/follow</code>。</li><li>详情请参阅<a href="./03-favorite-and-follow-systems.html">收藏与关注系统</a>。</li></ul><h2 id="数据库表结构" tabindex="-1">数据库表结构 <a class="header-anchor" href="#数据库表结构" aria-label="Permalink to &quot;数据库表结构&quot;">​</a></h2><p>该服务主要与以下表交互：</p><ul><li><code>zfeed_like</code>：存储当前点赞状态。</li><li><code>zfeed_comment</code>：存储楼中楼评论内容。</li><li><code>zfeed_favorite</code>：存储用户收藏。</li><li><code>zfeed_follow</code>：存储社交图谱。</li><li><code>zfeed_like_event_outbox</code>：可靠事件缓冲区。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#L51-L53" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#51-53</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#L19-L31" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_event_outbox_repository.go#19-31</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go#L170-L174" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go#170-174</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/producer/like_producer_test.go#L24-L38" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/producer/like_producer_test.go#24-38</a></p>',32)])])}const h=r(a,[["render",n]]);export{f as __pageData,h as default};
